def docs_updated_for_quest(repo_path: Path, base_ref: str, project_docs_rel: str) -> bool:
    if not base_ref:
        return False
    docs_rel = _normalize_repo_relative_path(project_docs_rel)
    checks: list[list[str]] = [
        ["diff", "--name-only", base_ref, "HEAD", "--", docs_rel],
        ["diff", "--name-only", base_ref, "--", docs_rel],
        ["ls-files", "--others", "--exclude-standard", "--", docs_rel],
    ]
    for args in checks:
        proc = subprocess.run(
            ["git", "-C", str(repo_path), *args],
            capture_output=True,
            text=True,
        )
        if proc.returncode == 0 and any(x.strip() for x in proc.stdout.splitlines()):
            return True
    return False


def _repo_root_for_quest_dir(quest_dir: Path) -> Path:
    cur = quest_dir.resolve()
    for _ in range(30):
        if (cur / ".git").exists():
            return cur
        parent = cur.parent
        if parent == cur:
            break
        cur = parent
    return quest_dir.resolve()


def role_thread_key(role_name: str, slice_dir: Path | None) -> str:
    from .workflow_profile_execution import (
        build_profile_execution_context,
        render_thread_registry_key,
        resolve_quest_workflow,
    )

    if slice_dir is None:
        from .workflow_config import load_packaged_default_workflow

        workflow = load_packaged_default_workflow()
        try:
            profile = workflow.get_profile(role_name)
        except KeyError:
            return role_name
        if profile.thread_scope == "quest":
            return role_name
        fatal_invariant(f"role_thread_key requires slice_dir for profile {role_name!r}")

    quest_dir = slice_dir.parents[1]
    workflow = resolve_quest_workflow(quest_dir)
    profile = workflow.get_profile(role_name)
    repo_path = _repo_root_for_quest_dir(quest_dir)
    meta = quest_fs.read_quest_meta(quest_dir)
    exec_ctx = build_profile_execution_context(
        repo_path=repo_path,
        quest_dir=quest_dir,
        machine_dir=slice_dir,
        meta=meta,
        workflow=workflow,
        profile=profile,
        profile_name=role_name,
        quest_docs_dir=runtime_quest_docs_dir(),
        active_child_dir=slice_dir,
        collection_name="slices",
    )
    return render_thread_registry_key(exec_ctx)


@dataclass
class TransitionPlan:
    """Describes all state changes for a single runner step."""

    quest_prev: QuestState | None = None
    quest_next: QuestState | None = None
    slice_dir: Path | None = None
    slice_prev: SliceState | None = None
    slice_next: SliceState | None = None
    new_current_slice: int | None = None
    scaffold_slice: bool = False

    @property
    def has_quest_transition(self) -> bool:
        return self.quest_prev is not None and self.quest_next is not None

    @property
    def has_slice_transition(self) -> bool:
        return self.slice_prev is not None and self.slice_next is not None

    @property
    def is_noop(self) -> bool:
        return not self.has_quest_transition and not self.has_slice_transition

"""Service-level harness provider configuration."""

from __future__ import annotations

import json
from pathlib import Path

from .quest_types import HarnessKind


def service_harness_config_path(repo_path: Path) -> Path:
    return (repo_path.resolve() / "config" / "quest-runner.json").resolve()


def read_service_harness_configs(repo_path: Path) -> dict[str, dict[str, object]]:
    """Load harness provider config from repository-root ``config/quest-runner.json``."""
    path = service_harness_config_path(repo_path)
    if not path.is_file():
        return {}
    raw_any = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(raw_any, dict):
        raise ValueError(f"{path} must be a JSON object")
    harnesses = raw_any.get("harnesses", {})
    if harnesses is None:
        return {}
    if not isinstance(harnesses, dict):
        raise ValueError(f"{path}: 'harnesses' must be a mapping")
    out: dict[str, dict[str, object]] = {}
    for harness_name, config in harnesses.items():
        if not isinstance(harness_name, str):
            raise ValueError(f"{path}: harness config keys must be strings")
        try:
            HarnessKind(harness_name)
        except ValueError as e:
            raise ValueError(f"{path}: unknown harness {harness_name!r}") from e
        if not isinstance(config, dict):
            raise ValueError(f"{path}: harness config {harness_name!r} must be a mapping")
        out[harness_name] = dict(config)
    return out

