def _format_issue_list(data: dict[str, Any], out: TextIO) -> None:
    issues = data.get("issues", [])
    if not isinstance(issues, list):
        issues = []
    rows = [
        [
            str(item.get("issue_id", "")),
            str(item.get("status", "")),
            str(item.get("title", "")),
